"""Record intrinsic BMP complexity with neutral first-party cmap 12/13 fonts."""
import argparse,json,struct,subprocess
from pathlib import Path
from fontTools.ttLib import TTFont,newTable
from fontTools.ttLib.tables._c_m_a_p import CmapSubtable
from gsub_execution_oracle import make_font,lookup,single,identity

def run(root,exe):
    root.mkdir(parents=True,exist_ok=True);observations=[]
    for fmt,glyph in [(12,'A'),(13,'A'),(13,'B')]:
        p=root/f'neutral-{fmt}-{glyph}.ttf';make_font(p,dict(name=f'neutral-{fmt}-{glyph}',lookups=[lookup(1,single({'A':'A'}))]))
        with TTFont(p,recalcTimestamp=False) as f:
            del f['GSUB'];del f['GDEF'];table=CmapSubtable.newSubtable(fmt);table.platformID=3 if fmt==12 else 0;table.platEncID=10 if fmt==12 else 6;table.language=0;table.cmap={cp:glyph for cp in range(65536) if not 0xd800<=cp<=0xdfff};f['cmap']=newTable('cmap');f['cmap'].tableVersion=0;f['cmap'].tables=[table];f.save(p)
        command=[str(exe.resolve()),str(p.resolve()),'61','default','1148846080','0','0','en-US','bmp-complexity'];r=subprocess.run(command,capture_output=True,text=True,timeout=45);assert r.returncode==0,(p,r.returncode,r.stdout,r.stderr);v=json.loads(r.stdout);assert v['hresult']==0 and v['mapped_scalars']==63488 and len(v['simple_words'])==2048
        observations.append(dict(font=identity(p),result=v))
    assert all(o['result']['simple_words']==observations[0]['result']['simple_words'] for o in observations)
    data=dict(reference=identity(exe),dwrite=identity(Path(observations[0]['result']['dwrite_module'])),observations=observations);(root/'observations.json').write_text(json.dumps(data,indent=2)+'\n')
    raw=struct.pack('<2048I',*observations[0]['result']['simple_words']);(root/'simple-bmp.bin').write_bytes(raw)
    pages=[raw[i:i+32] for i in range(0,len(raw),32)];unique=list(dict.fromkeys(pages));print(json.dumps(dict(fonts=len(observations),simple_scalars=observations[0]['result']['simple_scalars'],unique_pages=len(unique),page_table_bytes=256+32*len(unique)),indent=2))
def export(root,header,test_header=None):
    raw=(root/'simple-bmp.bin').read_bytes();assert len(raw)==8192;pages=[raw[i:i+32] for i in range(0,len(raw),32)];unique=list(dict.fromkeys(pages));assert len(unique)<=256
    indices=[unique.index(page) for page in pages];words=struct.unpack('<'+'Q'*(len(unique)*4),b''.join(unique))
    text='// First-party nominal compatibility profile derived from Windows behavior.\n// Generated by tools/font_reference/nominal_scalar_oracle.py; not general Unicode data.\n'
    text+='constexpr u8 nominal_page_index[256]{\n'+'\n'.join('    '+','.join(str(x) for x in indices[i:i+32])+',' for i in range(0,256,32))+'\n};\n'
    text+='constexpr u64 nominal_page_words[]{\n'+'\n'.join('    '+','.join(f'0x{x:016x}ull' for x in words[i:i+4])+',' for i in range(0,len(words),4))+'\n};\n'
    header.write_text(text);print(f'Exported {256+len(words)*8} profile bytes')
    if test_header:test_header.write_text('// Uncompressed Windows observation, independent of native page encoding.\nconstexpr u8 nominal_scalar_fixture[]{\n'+'\n'.join('    '+','.join(str(x) for x in raw[i:i+32])+',' for i in range(0,len(raw),32))+'\n};\n')
if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('root',type=Path);p.add_argument('--exe',type=Path);p.add_argument('--header',type=Path);p.add_argument('--test-header',type=Path);a=p.parse_args()
    if a.exe:run(a.root,a.exe)
    if a.header:export(a.root,a.header,a.test_header)
